// roleAtTable é a sobrancelha: o que EU sou aqui. O nome do dono só aparece
// para ADMIN que não é dono — para o jogador, marcar a mesa trocaria o
// "Jogando" dele por "Mesa de Fulano", que é defeito que o e2e já pegou.
func roleAtTable(v oneView) string {
	switch {
	case v.EhMestre:
		return "Mestrando"
	case v.DonoOutro != "":
		return "Mesa de " + v.DonoOutro
	default:
		return "Jogando"
	}
}

// tableMeta é a linha de baixo: o tamanho do grupo e desde quando ela existe.
func tableMeta(v oneView) string {
	linha := ui.Plural(int64(v.TotalHerois), "herói", "heróis")
	if v.CriadaEm != "" {
		linha += " · Criada em " + v.CriadaEm
	}
	return linha
}

// tabLayout: o painel e o elenco são grades; a linha do tempo e o formulário
// são listas. É o que faz a seta andar como o olho vê.
func tabLayout(aba string) string {
	if aba == "visao" || aba == "membros" {
		return "grid"
	}
	return "column"
}

